from pathlib import Path
import re,csv
lines=Path('/app/dataset/genealogy_trees.txt').read_text().splitlines()
# matches letter words separated by a single space; 2+ spaces split naturally
pat=re.compile(r'[^\W\d_]+(?: [^\W\d_]+)*', re.UNICODE)
segs=[]
for y,l in enumerate(lines):
    for m in pat.finditer(l):
        txt=m.group(0)
        # skip headers FAMILY TREE GENERATOR? maybe keep
        segs.append((y,m.start(),m.end(),txt))
print('segments', len(segs))
for s in segs[:40]: print(s)
print('around target')
for s in segs:
    y,x1,x2,t=s
    if 2860<=x1<=3000 and 80<=y+1<=99:
        print(y+1,x1,x2,repr(t))
# exact text segment count for csv full names/first/last
rows=list(csv.DictReader(open('/app/dataset/people_accounts.csv')))
full=0; split_cands=0; missing=[]
seg_by_text={}
for seg in segs: seg_by_text.setdefault(seg[3],[]).append(seg)
for r in rows:
    fn,ln=r['first_name'],r['last_name']; name=fn+' '+ln
    if name in seg_by_text: full+=1
    else:
        # adjacent first/last within same x approx
        cand=False
        for s1 in seg_by_text.get(fn,[]):
            for s2 in seg_by_text.get(ln,[]):
                if abs(s1[0]-s2[0])<=2 and max(s1[1],s2[1]) <= min(s1[2],s2[2])+20:
                    cand=True; break
            if cand: break
        if cand: split_cands+=1
        else: missing.append(name)
print('full seg',full,'split cand',split_cands,'missing',len(missing))
print(missing[:50])
