def answer() -> int:
    import csv

    qualifying_children = {"Liwia Maligłówka", "Alan Wocial"}
    total = 0

    with open("/app/dataset/people_accounts.csv", newline="") as f:
        for row in csv.DictReader(f):
            name = f"{row['first_name']} {row['last_name']}"
            if name in qualifying_children:
                total += int(row["account_balance"])

    return total


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
